+// object component of ty is not a single atom.
+func ObjectMemberVisibilities(ctx Context, ty SemType) (map[string]string, bool) {
+	atom := ToObjectAtomicType(ctx, ty)
+	if atom == nil {
+		return nil, false
+	}
+	visibilityKey := StringConst("visibility")
+	regions := make(map[string]string, len(atom.names))
+	for i, name := range atom.names {
+		shape := SingleShape(mappingMemberTypeInner(ctx, CellInnerVal(atom.types[i]), visibilityKey))
+		if shape.IsEmpty() {
+			continue
+		}
+		if region, ok := shape.Get().Value.(string); ok {
+			regions[name] = region
+		}
+	}
+	return regions, true
